const LIQ44=[
 {m:'Sep',calls:.92,dist:.18,fees:.09,other:.04,event:'Growth Equity IV · capital call',date:'08 Sep',prob:'90%'},
 {m:'Oct',calls:.66,dist:.44,fees:.09,other:.03,event:'Infrastructure Fund II · call',date:'17 Oct',prob:'80%'},
 {m:'Nov',calls:.38,dist:.72,fees:.10,other:.03,event:'Africa Payments II · distribution',date:'11 Nov',prob:'70%'},
 {m:'Dec',calls:.28,dist:.19,fees:.11,other:.04,event:'Real Assets SPV · capex draw',date:'09 Dec',prob:'75%'},
 {m:'Jan',calls:.74,dist:.24,fees:.09,other:.03,event:'Growth Equity V · call',date:'21 Jan',prob:'65%'},
 {m:'Feb',calls:.31,dist:.62,fees:.08,other:.02,event:'Property Credit I · repayment',date:'14 Feb',prob:'70%'},
 {m:'Mar',calls:.44,dist:.27,fees:.08,other:.03,event:'Solar Platform II · draw',date:'07 Mar',prob:'60%'},
 {m:'Apr',calls:.22,dist:.58,fees:.08,other:.02,event:'Africa Payments II · distribution',date:'24 Apr',prob:'60%'},
 {m:'May',calls:.54,dist:.31,fees:.08,other:.02,event:'Logistics Park · capex draw',date:'11 May',prob:'70%'},
 {m:'Jun',calls:.29,dist:.81,fees:.08,other:.02,event:'Africa Payments II · distribution',date:'27 Jun',prob:'55%'},
 {m:'Jul',calls:.67,dist:.39,fees:.08,other:.03,event:'Growth Equity V · first call',date:'09 Jul',prob:'50%'},
 {m:'Aug',calls:.38,dist:.74,fees:.09,other:.02,event:'Solar Platform II · distribution',date:'18 Aug',prob:'45%'}
];
let liq44={scenario:'base',horizon:6,view:'gross',selected:0};
function liqRows44(){const mult=liq44.scenario==='downside'?{calls:1.28,dist:.62,fees:1.12}:liq44.scenario==='upside'?{calls:.90,dist:1.22,fees:.95}:{calls:1,dist:1,fees:1};return LIQ44.slice(0,liq44.horizon).map(x=>({...x,calls:x.calls*mult.calls,dist:x.dist*mult.dist,fees:x.fees*mult.fees}))}
function liqCalc44(){const rows=liqRows44(),start=7.20;let cash=start,min=start;const out=[];rows.forEach(r=>{cash+=r.dist-r.calls-r.fees-r.other;min=Math.min(min,cash);out.push({...r,cash})});const calls=rows.reduce((a,r)=>a+r.calls,0),dist=rows.reduce((a,r)=>a+r.dist,0),fees=rows.reduce((a,r)=>a+r.fees+r.other,0),net=dist-calls-fees,peak=Math.max(...rows.map(r=>r.calls+r.fees+r.other),.01),cover=min/peak;return{rows:out,start,end:cash,min,calls,dist,fees,net,cover}}
function liqChartSvg44(){
 const d=liqCalc44(),rows=d.rows,W=980,H=380,L=62,R=76,T=25,B=52,plotW=W-L-R,plotH=H-T-B;
 const maxFlow=Math.max(...rows.flatMap(r=>[r.calls+r.fees+r.other,r.dist]),.5)*1.18,maxCash=Math.max(d.start,...rows.map(r=>r.cash))*1.10,minCash=Math.min(0,Math.min(...rows.map(r=>r.cash))*.9),flowTop=T+8,flowBottom=T+plotH*.54,cashTop=T+plotH*.12,cashBottom=T+plotH*.88;
 const x=i=>L+plotW*(i+.5)/rows.length,barW=Math.max(14,Math.min(28,plotW/rows.length*.23)),fy=v=>flowBottom-(flowBottom-flowTop)*(v/maxFlow),cy=v=>cashBottom-(cashBottom-cashTop)*((v-minCash)/(maxCash-minCash||1));
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Monthly calls distributions and liquidity runway"><defs><linearGradient id="v44cashArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#121d2f" stop-opacity=".12"/><stop offset="1" stop-color="#121d2f" stop-opacity="0"/></linearGradient></defs>`;
 for(let i=0;i<=4;i++){const v=maxCash-(maxCash-minCash)*i/4,yy=cy(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e8edf3"/><text x="${W-R+9}" y="${yy+4}">${v.toFixed(1)}m</text>`}
 svg+=`<text class="axis-title" x="${W-R+9}" y="${T+2}">LIQUID ASSETS</text><text class="axis-title" x="${L}" y="${T+2}">MONTHLY FLOW · US$m</text>`;
 [0,maxFlow/2,maxFlow].forEach(v=>{const yy=fy(v);svg+=`<text x="${L-9}" y="${yy+4}" text-anchor="end">${v.toFixed(1)}</text>`});
 let pts=[];rows.forEach((r,i)=>{const xx=x(i),calls=r.calls+r.fees+r.other,callH=flowBottom-fy(calls),distH=flowBottom-fy(r.dist),net=r.dist-calls;
  if(liq44.view==='gross'){
   svg+=`<rect x="${xx-barW-4}" y="${flowBottom-callH}" width="${barW}" height="${callH}" rx="4" fill="#2d63ef" opacity=".88"/><rect x="${xx+4}" y="${flowBottom-distH}" width="${barW}" height="${distH}" rx="4" fill="#0aa4b1" opacity=".88"/><rect x="${xx-barW-4}" y="${flowBottom-(r.fees+r.other)/maxFlow*(flowBottom-flowTop)}" width="${barW}" height="${(r.fees+r.other)/maxFlow*(flowBottom-flowTop)}" rx="3" fill="#9dabbd"/>`;
  }else{
   const h=Math.abs(net)/maxFlow*(flowBottom-flowTop);svg+=`<rect x="${xx-barW/2}" y="${net>=0?flowBottom-h:flowBottom}" width="${barW}" height="${h}" rx="4" fill="${net>=0?'#0aa4b1':'#2d63ef'}" opacity=".9"/>`;
  }
  pts.push([xx,cy(r.cash),r.cash]);svg+=`<text x="${xx}" y="${H-18}" text-anchor="middle">${esc(r.m)}</text><rect class="month-hit" data-liq-index="${i}" x="${xx-plotW/rows.length/2}" y="${T}" width="${plotW/rows.length}" height="${H-T-B}"/>`;
 });
 const pd=pts.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' '),area=`${pd} L${pts.at(-1)[0]},${cashBottom} L${pts[0][0]},${cashBottom} Z`;svg+=`<path d="${area}" fill="url(#v44cashArea)"/><path d="${pd}" fill="none" stroke="#121d2f" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>`;
 pts.forEach((p,i)=>svg+=`<circle data-liq-point="${i}" cx="${p[0]}" cy="${p[1]}" r="${i===liq44.selected?5:3.5}" fill="#fff" stroke="#121d2f" stroke-width="2"/>`);
 const floorCash=Math.max(0,Math.min(maxCash,d.min/1.25)),floorY=cy(floorCash);svg+=`<line x1="${L}" x2="${W-R}" y1="${floorY}" y2="${floorY}" stroke="#d28a15" stroke-width="1.4" stroke-dasharray="6 5"/><text x="${L+6}" y="${floorY-7}" fill="#9b6508" font-weight="750">House liquidity floor</text></svg>`;return svg
}
function renderLiquidity44(){const host=$('#v35LiquidityPanel');if(!host)return;host.classList.add('v44-liquidity');const d=liqCalc44(),s=d.rows[clamp(liq44.selected,0,d.rows.length-1)]||d.rows[0],coverPct=clamp(d.cover/2*100,0,100);host.innerHTML=`<div class="v44-liq-head"><div><div class="v44-kicker">LIQUIDITY PLANNING · PRIVATE MARKETS</div><h2>Private-market cashflow forecast</h2><p>See the timing of calls and distributions without compressing the runway. The chart separates monthly flow from liquid-asset capacity, and every month can be inspected.</p></div><div class="v44-liq-controls"><div class="v44-seg">${[['base','Base'],['downside','Downside'],['upside','Upside']].map(x=>`<button data-v44-liq-scenario="${x[0]}" class="${liq44.scenario===x[0]?'active':''}">${x[1]}</button>`).join('')}</div><div class="v44-seg">${[[3,'90D'],[6,'6M'],[12,'12M']].map(x=>`<button data-v44-liq-horizon="${x[0]}" class="${liq44.horizon===x[0]?'active':''}">${x[1]}</button>`).join('')}</div><div class="v44-seg"><button data-v44-liq-view="gross" class="${liq44.view==='gross'?'active':''}">Gross flows</button><button data-v44-liq-view="net" class="${liq44.view==='net'?'active':''}">Net flow</button></div></div></div><div class="v44-liq-kpis"><div class="v44-liq-kpi"><span>Opening liquidity</span><strong>US$ ${d.start.toFixed(2)}m</strong><small>Cash + eligible short term</small></div><div class="v44-liq-kpi"><span>Projected calls</span><strong>US$ ${d.calls.toFixed(2)}m</strong><small>${liq44.scenario} pacing</small></div><div class="v44-liq-kpi"><span>Distributions</span><strong>US$ ${d.dist.toFixed(2)}m</strong><small>Probability weighted</small></div><div class="v44-liq-kpi"><span>Fees / other</span><strong>US$ ${d.fees.toFixed(2)}m</strong><small>Fund + direct costs</small></div><div class="v44-liq-kpi"><span>Net private flow</span><strong>${d.net<0?'−':'+'}US$ ${Math.abs(d.net).toFixed(2)}m</strong><small>${liq44.horizon===3?'90-day':liq44.horizon+'-month'} horizon</small></div><div class="v44-liq-kpi"><span>Ending liquidity</span><strong>${d.end<0?'−':''}US$ ${Math.abs(d.end).toFixed(2)}m</strong><small>Before discretionary trades</small></div></div><div class="v44-liq-main"><section class="v44-liq-chart-card"><div class="v44-liq-chart-head"><div><strong>Monthly calls, distributions and liquidity runway</strong><small>Click or hover a month to inspect the cash event and closing liquidity.</small></div><div class="v44-liq-legend"><span><i></i>Calls / outflows</span><span class="dist"><i></i>Distributions</span><span class="fees"><i></i>Fees / other</span><span class="cash"><i></i>Liquid assets</span></div></div><div class="v44-liq-chart-scroll"><div class="v44-liq-chart" id="v44LiquidityChart">${liqChartSvg44()}<div class="v44-chart-tip" id="v44LiqTip"></div></div></div><div class="v44-liq-selected"><div><span>Selected month</span><strong>${esc(s.m)}</strong></div><div><span>Calls / outflows</span><strong>US$ ${(s.calls+s.fees+s.other).toFixed(2)}m</strong></div><div><span>Distributions</span><strong>US$ ${s.dist.toFixed(2)}m</strong></div><div><span>Closing liquidity</span><strong>US$ ${s.cash.toFixed(2)}m</strong></div></div></section><aside class="v44-liq-side-card"><div class="v44-cover"><div class="v44-cover-ring" style="--p:${coverPct.toFixed(0)};--c:${d.cover>=1.25?'#087a63':'#bf3048'}"><div><strong>${d.cover.toFixed(2)}×</strong><small>cover</small></div></div><div><h3>Minimum liquidity cover</h3><p>${d.cover>=1.25?'Above the 1.25× house floor. Capacity remains available, subject to settlement and margin reserves.':'Below the 1.25× house floor. Funding action is required before new commitments.'}</p></div></div><div class="v44-funding"><div class="v44-kicker">FUNDING WATERFALL</div><div class="v44-funding-row"><span>Free USD operating cash</span><strong>US$ 3.42m</strong></div><div class="v44-funding-row"><span>T-bills / MMF same-day</span><strong>US$ 2.08m</strong></div><div class="v44-funding-row"><span>Committed liquidity line</span><strong>US$ 1.70m</strong></div><div class="v44-funding-row"><span>Reserved for settlement / margin</span><strong>US$ 0.84m</strong></div><button class="v44-btn" id="v44FundingPlan">Open funding plan</button></div></aside></div><div class="v44-liq-events"><div class="v44-liq-events-head"><strong>Next material private-market cash events</strong><button class="v44-btn" id="v44StressLiq">Apply downside stress</button></div><div class="v44-liq-event-grid">${d.rows.slice(0,4).map((r,i)=>`<button class="v44-liq-event" data-v44-event="${i}"><span>${esc(r.date)} · ${esc(r.prob)} confidence</span><strong>${esc(r.event)}</strong><small>${esc(r.m)} liquidity plan</small><em>${r.dist>(r.calls+r.fees+r.other)?'+':'−'}US$ ${Math.abs(r.dist-(r.calls+r.fees+r.other)).toFixed(2)}m net</em></button>`).join('')}</div></div>`;
 $$('[data-v44-liq-scenario]',host).forEach(b=>b.onclick=()=>{liq44.scenario=b.dataset.v44LiqScenario;liq44.selected=0;renderLiquidity44()});$$('[data-v44-liq-horizon]',host).forEach(b=>b.onclick=()=>{liq44.horizon=+b.dataset.v44LiqHorizon;liq44.selected=0;renderLiquidity44()});$$('[data-v44-liq-view]',host).forEach(b=>b.onclick=()=>{liq44.view=b.dataset.v44LiqView;renderLiquidity44()});
 const chart=$('#v44LiquidityChart',host),svg=$('svg',chart),tip=$('#v44LiqTip',chart);$$('[data-liq-index]',svg).forEach(hit=>{const idx=+hit.dataset.liqIndex;const show=e=>{const r=d.rows[idx],box=chart.getBoundingClientRect();tip.style.display='block';tip.innerHTML=`<strong>${esc(r.m)} · US$ ${r.cash.toFixed(2)}m closing liquidity</strong><span>Calls/outflows: US$ ${(r.calls+r.fees+r.other).toFixed(2)}m</span><span>Distributions: US$ ${r.dist.toFixed(2)}m</span><span>${esc(r.event)}</span>`;tip.style.left=clamp((e.clientX-box.left)+10,6,box.width-185)+'px';tip.style.top=clamp((e.clientY-box.top)-54,6,box.height-90)+'px'};hit.onpointermove=show;hit.onpointerdown=e=>{liq44.selected=idx;renderLiquidity44()};hit.onpointerleave=()=>tip.style.display='none'});
 $$('[data-v44-event]',host).forEach(b=>b.onclick=()=>{liq44.selected=+b.dataset.v44Event;renderLiquidity44()});$('#v44StressLiq',host).onclick=()=>{liq44.scenario='downside';liq44.selected=0;renderLiquidity44();toast44('Downside stress applied','Calls accelerated and distributions haircut. Review the minimum liquidity point before new commitments.')};$('#v44FundingPlan',host).onclick=()=>openModal44({kicker:'PRIVATE MARKETS · FUNDING PLAN',title:'Funding sequence',subtitle:'Convert forecast needs into controlled funding actions.',body:`<div class="v44-recon-playbook"><div><span>1 · Protect</span><strong>Settlement & margin reserve</strong><small>Keep US$ 0.84m ring-fenced.</small></div><div><span>2 · Use</span><strong>Free operating cash</strong><small>US$ 3.42m available without liquidation.</small></div><div><span>3 · Monetise</span><strong>T-bills / MMF</strong><small>US$ 2.08m same-day / T+1.</small></div></div>`})
}

