function openReconImport44(r){const m=openModal44({kicker:'RECONCILIATION · SOURCE INGESTION',title:'Add independent evidence',subtitle:'Register a bank, broker, custodian or transfer-agent source before matching.',body:`<div class="v44-order-form"><label class="v44-order-field"><span>Provider</span><input id="v44ReconProvider" placeholder="Bank / broker / custodian"></label><label class="v44-order-field"><span>Control family</span><select id="v44ReconImportFamily"><option>${esc(r?.family||'Cash')}</option><option>Cash</option><option>Holdings</option><option>Trades</option><option>Settlement</option></select></label><label class="v44-order-field wide"><span>Source file</span><input id="v44ReconFile" type="file" accept=".csv,.txt,.json,.xml"></label><label class="v44-order-field wide"><span>Preview</span><textarea id="v44ReconPreview" readonly placeholder="Select a file to preview metadata"></textarea></label></div>`,footer:'<button class="v44-btn" id="v44ReconImportCancel">Cancel</button><button class="v44-btn primary" id="v44ReconImportSave" disabled>Validate & register</button>'});$('#v44ReconImportCancel',m).onclick=closeModal44;let fmeta=null;$('#v44ReconFile',m).onchange=e=>{const f=e.target.files?.[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{const txt=String(rd.result||'');fmeta={name:f.name,rows:txt.split(/\r?\n/).filter(Boolean).length};$('#v44ReconPreview',m).value=`${f.name}\n${f.size.toLocaleString()} bytes\n${fmeta.rows} non-empty rows\nReady for controlled source registration`;$('#v44ReconImportSave',m).disabled=false};rd.readAsText(f)};$('#v44ReconImportSave',m).onclick=()=>{if(!$('#v44ReconProvider',m).value.trim())return toast44('Provider required','Name the independent source.','error');if(r?.group==='Waiting source'){r.group='Needs action';r.status='Source received';r.severity='high';r.external.value='Source received · matching required';r.next='Validate the newly received source and run matching.'}closeModal44();renderReconAll44();toast44('Source registered',`${fmeta?.name||'Evidence'} is available for validation and matching.`)}}
function buildReconciliations44(){const p=$('#page-reconciliations');if(!p)return;p.className='page v44-recon';const k=reconKpis44();p.innerHTML=`<div class="v44-recon-shell"><header class="v44-recon-head"><div><div class="v44-kicker">INDEPENDENT EVIDENCE · MATCHING · INVESTIGATION · MAKER / CHECKER</div><h1>Reconciliations</h1><p>Work from the question that matters: what needs attention, why is it different, what evidence proves it, and who must act next. Routine matches stay out of the way.</p></div><div class="v44-recon-actions"><button class="v44-btn" id="v44ReconSourceRuns">Source health</button><button class="v44-btn" id="v44ReconImport">Import evidence</button><button class="v44-btn primary" id="v44ReconRun">Run matching</button></div></header><section class="v44-recon-kpis"><article class="v44-recon-kpi"><span>Needs my action</span><strong id="v44ReconAction">${k.action}</strong><small>Genuine differences only</small></article><article class="v44-recon-kpi"><span>Waiting source</span><strong id="v44ReconWaiting">${k.waiting}</strong><small>Not classified as breaks</small></article><article class="v44-recon-kpi"><span>Ready checker</span><strong id="v44ReconChecker">${k.checker}</strong><small>Maker work complete</small></article><article class="v44-recon-kpi"><span>Matched today</span><strong id="v44ReconMatched">${k.matched}</strong><small>Auto-matched + approved</small></article></section><section class="v44-recon-journey"><div class="v44-recon-stage done"><b>1</b><span><strong>Gather evidence</strong><small>Books + independent sources</small></span></div><div class="v44-recon-stage done"><b>2</b><span><strong>Match</strong><small>Rules + tolerances</small></span></div><div class="v44-recon-stage active"><b>3</b><span><strong>Investigate</strong><small>Only real differences</small></span></div><div class="v44-recon-stage"><b>4</b><span><strong>Fix & re-match</strong><small>Maker correction</small></span></div><div class="v44-recon-stage"><b>5</b><span><strong>Sign off</strong><small>Independent checker</small></span></div></section><div class="v44-recon-tools"><input class="v44-recon-search" id="v44ReconSearch" placeholder="Search account, order, security, source or owner"><select class="v44-recon-select" id="v44ReconScope"><option>My tasks</option><option>All</option></select><select class="v44-recon-select" id="v44ReconFamily"><option>All</option>${[...new Set(recon44.map(r=>r.family))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="v44-btn" id="v44ReconSignoff">Daily sign-off</button></div><div class="v44-recon-workbench"><aside class="v44-recon-queue-card"><div class="v44-recon-card-head"><div><div class="v44-kicker">WORK QUEUE</div><h2>What needs attention</h2><p>Prioritised by action state, not by system jargon.</p></div></div><div class="v44-recon-queue" id="v44ReconQueue"></div></aside><main class="v44-recon-detail" id="v44ReconDetail"></main></div></div>`;renderReconAll44();$('#v44ReconSearch').oninput=e=>{recon44State.query=e.target.value.toLowerCase();renderReconQueue44()};$('#v44ReconScope').onchange=e=>{recon44State.scope=e.target.value;const a=reconFiltered44();if(a[0])recon44State.selected=a[0].id;renderReconAll44()};$('#v44ReconFamily').onchange=e=>{recon44State.family=e.target.value;const a=reconFiltered44();if(a[0])recon44State.selected=a[0].id;renderReconAll44()};$('#v44ReconImport').onclick=()=>openReconImport44();$('#v44ReconRun').onclick=()=>toast44('Matching complete','Current sources validated. Routine matches cleared and genuine differences remain in the action queue.');$('#v44ReconSourceRuns').onclick=()=>openModal44({kicker:'RECONCILIATION · SOURCE HEALTH',title:'Independent source readiness',subtitle:'Matching only runs on complete, validated populations.',body:`<div class="v44-recon-playbook"><div><span>Bank</span><strong>3 / 3 current</strong><small>Statements and API cash feeds validated.</small></div><div><span>Brokers</span><strong>4 / 4 current</strong><small>FIX and contract-note populations current.</small></div><div><span>Custodians</span><strong>3 / 4 current</strong><small>Custodian B cash source is late.</small></div></div>`});$('#v44ReconSignoff').onclick=()=>openModal44({kicker:'RECONCILIATION · DAILY SIGN-OFF',title:'Close readiness is conditional',subtitle:'Resolve material exceptions and receive required sources before final close.',body:`<div class="v44-recon-playbook"><div><span>Books</span><strong>Frozen</strong><small>IBOR / OMS / ABOR cut-off retained.</small></div><div><span>Sources</span><strong>1 late</strong><small>Custodian B cash file outstanding.</small></div><div><span>Checker</span><strong>Segregated</strong><small>Independent approval remains enforced.</small></div></div>`})}

