function bindOrderIntercept44(){window.addEventListener('click',e=>{const t=e.target.closest?.('#v33NewOrder,#v33OrderAtPrice,#v35QuickDeal,#v33SellPosition');if(!t||!$('#page-orders')?.classList.contains('active'))return;e.preventDefault();e.stopImmediatePropagation();openOrder44(t.id==='v33SellPosition'?'Sell':'Buy',t.id==='v33OrderAtPrice'?Number(currentSec44().last):null)},true)}

